// ============================================================================
// Auth State Tests
// ============================================================================

/// Test that AuthState can be created and modified.
#[test]
fn test_auth_state_transitions() {
    // Test logical auth state without UI
    // This verifies the state model that UI callbacks would use

    #[derive(Default, Clone)]
    struct MockAuthState {
        logged_in: bool,
        user_id: Option<String>,
        display_name: Option<String>,
        device_id: Option<u32>,
    }

    let mut state = MockAuthState::default();

    // Initial state
    assert!(!state.logged_in);
    assert!(state.user_id.is_none());

    // Simulate login callback setting state
    state.logged_in = true;
    state.user_id = Some("user-123".to_string());
    state.display_name = Some("Test User".to_string());
    state.device_id = Some(1);

    assert!(state.logged_in);
    assert_eq!(state.user_id, Some("user-123".to_string()));

    // Simulate logout callback
    state.logged_in = false;
    state.user_id = None;
    state.display_name = None;
    state.device_id = None;

    assert!(!state.logged_in);
    assert!(state.user_id.is_none());
}

// ============================================================================
// View State Tests
// ============================================================================

#[test]
fn test_view_state_transitions() {
    // Test view state without UI
    // Views: "loading", "login", "register", "main"

    #[derive(Default, Clone, PartialEq, Debug)]
    enum ViewState {
        #[default]
        Loading,
        Login,
        Register,
        Main,
    }

    let mut view = ViewState::Loading;

    // App starts loading
    assert_eq!(view, ViewState::Loading);

    // No session, go to login
    view = ViewState::Login;
    assert_eq!(view, ViewState::Login);

    // User clicks "go to register"
    view = ViewState::Register;
    assert_eq!(view, ViewState::Register);

    // User clicks "go to login"
    view = ViewState::Login;
    assert_eq!(view, ViewState::Login);

    // Successful login
    view = ViewState::Main;
    assert_eq!(view, ViewState::Main);

    // Logout
    view = ViewState::Login;
    assert_eq!(view, ViewState::Login);
}

// ============================================================================
// Error State Tests
// ============================================================================

#[test]
fn test_error_state_handling() {
    // Test error state management

    #[derive(Default, Clone)]
    struct MockErrorState {
        login_error: Option<String>,
        register_error: Option<String>,
        network_error: Option<String>,
    }

    let mut errors = MockErrorState::default();

    // Initial state - no errors
    assert!(errors.login_error.is_none());
    assert!(errors.register_error.is_none());

    // Simulate login failure
    errors.login_error = Some("Invalid username or password".to_string());
    assert!(errors.login_error.is_some());

    // User retries, error cleared before attempt
    errors.login_error = None;
    assert!(errors.login_error.is_none());

    // Network error during registration
    errors.register_error = Some("Connection failed".to_string());
    errors.network_error = Some("Unable to reach server".to_string());
    assert!(errors.register_error.is_some());
    assert!(errors.network_error.is_some());
}

// ============================================================================
// Callback Flow Tests (Integration with Server)
// ============================================================================

#[tokio::test]
async fn test_login_callback_flow() {
    skip_if_no_server!();

    // This test simulates what a login callback would do

    let pool = assert_ok(create_test_pool().await);
    let user = assert_ok(register_test_user(&pool).await);

    // Mock state
    let mut logged_in = false;
    let mut current_user_id: Option<String> = None;
    let mut login_error: Option<String> = None;
    let mut current_view = "login";

    // Simulate callback: on_login(username, password)
    use chatter_core::network::grpc::AuthClient;

    let mut auth_client = AuthClient::new(pool.channel(), pool.auth_clone());

    // Clear error before attempt
    login_error = None;

    let login_result = auth_client
        .login(
            &user.username,
            &user.password_hash,
            "test-device",
            &user.public_key,
            &user.device_auth_token,
            &random_uak(),
            None,
        )
        .await;

    match login_result {
        Ok(response) => {
            logged_in = true;
            // AuthResponse has user_profile, not user_id directly
            current_user_id = response.user_profile.map(|p| p.user_id);
            current_view = "main";
        }
        Err(e) => {
            logged_in = false;
            login_error = Some(e.to_string());
        }
    }

    // Verify callback results
    assert!(logged_in, "Should be logged in");
    assert!(current_user_id.is_some(), "Should have user ID");
    assert!(login_error.is_none(), "Should have no error");
    assert_eq!(current_view, "main", "Should switch to main view");
}

#[tokio::test]
async fn test_login_wrong_password_flow() {
    skip_if_no_server!();

    let pool = assert_ok(create_test_pool().await);
    let user = assert_ok(register_test_user(&pool).await);

    // Mock state
    let mut logged_in = false;
    let mut login_error: Option<String> = None;
    let mut current_view = "login";

    // Simulate callback with wrong password
    use chatter_core::network::grpc::AuthClient;
    use sha2::{Digest, Sha256};

    let wrong_password_hash = Sha256::digest(b"wrong_password").to_vec();

    let mut auth_client = AuthClient::new(pool.channel(), pool.auth_clone());

    let login_result = auth_client
        .login(
            &user.username,
            &wrong_password_hash,
            "test-device",
            &user.public_key,
            &user.device_auth_token,
            &random_uak(),
            None,
        )
        .await;

    match login_result {
        Ok(_response) => {
            logged_in = true;
            current_view = "main";
        }
        Err(e) => {
            logged_in = false;
            login_error = Some(e.to_string());
            // Stay on login view
        }
    }

    // Verify callback results
    assert!(!logged_in, "Should not be logged in");
    assert!(login_error.is_some(), "Should have error message");
    assert_eq!(current_view, "login", "Should stay on login view");
}

#[tokio::test]
async fn test_register_callback_flow() {
    skip_if_no_server!();

    let pool = assert_ok(create_test_pool().await);

    // Mock state
    let mut logged_in = false;
    let mut current_user_id: Option<String> = None;
    let mut current_view = "register";

    // Simulate callback: on_register(username, password, display_name)
    use chatter_core::network::grpc::AuthClient;

    let mut auth_client = AuthClient::new(pool.channel(), pool.auth_clone());

    let username = unique_username();
    let password_hash = random_password_hash();
    let device_auth_token = random_device_auth_token();
    let profile_key = random_profile_key();

    // Generate real prekey bundle with valid signatures
    let (prekey_bundle, identity_public_key) = generate_prekey_bundle();

    let register_result = auth_client
        .register_and_wait(
            &username,
            &password_hash,
            "Test User",
            &identity_public_key,
            "test-device",
            &device_auth_token,
            &profile_key,
            Some(prekey_bundle),
            Vec::new(),
        )
        .await;

    match register_result {
        Ok(result) => {
            logged_in = true;
            current_user_id = Some(result.user_id);
            current_view = "main";
        }
        Err(e) => {
            eprintln!("Registration error: {}", e);
        }
    }

    // Verify callback results
    assert!(logged_in, "Should be logged in after registration");
    assert!(current_user_id.is_some(), "Should have user ID");
    assert_eq!(current_view, "main", "Should switch to main view");
}

#[tokio::test]
async fn test_logout_callback_flow() {
    skip_if_no_server!();

    let pool = assert_ok(create_test_pool().await);
    let user = assert_ok(setup_authenticated_test(&pool).await);

    // Mock state - logged in
    let mut logged_in = true;
    let mut current_user_id: Option<String> = Some(user.user_id.clone());
    let mut current_view = "main";

    // Simulate callback: on_settings_logout()
    use chatter_core::network::grpc::AuthClient;

    let mut auth_client = AuthClient::new(pool.channel(), pool.auth_clone());

    let _logout_result = auth_client.logout(user.device_id).await;

    // Update state regardless of result (local logout)
    logged_in = false;
    current_user_id = None;
    current_view = "login";

    // Clear auth credentials
    pool.auth().clear();

    // Verify callback results
    assert!(!logged_in, "Should not be logged in");
    assert!(current_user_id.is_none(), "Should clear user ID");
    assert_eq!(current_view, "login", "Should switch to login view");
}
